def unread_count(user=Depends(require_level(1))):
    with get_conn() as c:
        row = c.execute(
            "SELECT COUNT(*) as cnt FROM notifications "
            "WHERE user_id = ? AND is_read = 0 "
            "AND type NOT IN ('chat_message', 'chat_attachment')",
            (user["id"],),
        ).fetchone()
    return {"unread": row["cnt"] if row else 0}
